$$ egin{align*}	extbf{I: 基本恒等式}
otag \ \sin^2 x + \cos^2 x &= 1 \ 	an x &=  rac{\sin x}{\cos x} \ 1 + 	an^2 x &= \sec^2 x \ 1 + \cot^2 x &= \csc^2 x \\hline	extbf{II: 诱导公式} 
otag \ (奇变偶不变，符号看象限) 
otag \ \sin(x+2k\pi) &= \sin x \ \cos(x+2k\pi) &= \cos x \ 	an(x+k\pi) &= 	an x \ \hdashline \sin(-x) &= -\sin x \ \cos(-x) &= \cos x \ 	an(-x) &= -	an x \ \hdashline \sin(\pi - x) &= \sin x \ \cos(\pi - x) &= -\cos x \ \hdashline \sin(\pi + x) &= -\sin x \ \cos(\pi + x) &= -\cos x \ \hdashline \sin( rac{\pi}{2}-x)&=\cos x \ \cos( rac{\pi}{2}-x)&=\sin x \ \hdashline \sin( rac{\pi}{2}+x)&=\cos x \ \cos( rac{\pi}{2}+x)&=-\sin x \\hline	extbf{III: 和差公式} \ \sin(a\pm b)&=\sin a\cos b\pm\cos a\sin b \ \cos(a\pm b)&=\cos a\cos b\mp\sin a\sin b \ 	an(a\pm b)&= rac{	an a\pm	an b}{1\mp	an a	an b} \\hline	extbf{IV: 二倍角公式} \ \sin 2x &= 2\sin x\cos x \ \cos 2x &= \cos^2 x - \sin^2 x \ &= 1 - 2\sin^2 x \ &= 2\cos^2 x - 1 \ 	an 2x &=  rac{2	an x}{1-	an^2 x} \\hline	extbf{V: 半角公式} \ \sin^2 rac{x}{2} &=  rac{1-\cos x}{2} \ \cos^2 rac{x}{2} &=  rac{1+\cos x}{2} \ 	an rac{x}{2} &=  rac{\sin x}{1+\cos x} \ 	an rac{x}{2} &=  rac{1-\cos x}{\sin x} \ 	an rac{x}{2} &=  rac{\sin x}{1+\cos x} \\end{align*}$$
